// Turns three.js example modules (FBXLoader, GLTFLoader, SkeletonUtils + what they import) into one classic script,
// vendor/three-addons.js, that uses the global THREE of vendor/three.min.js (same version, 0.160) and sets
// window.THREE_ADDONS = { FBXLoader, GLTFLoader, SkeletonUtils }.  The films' pages stay classic scripts, so the
// renderer (file://) and the live preview load them the same way.
//   node bundle-addons.js            (reads npm/package/examples/jsm, writes template/vendor/three-addons.js)
'use strict';
const fs = require('fs'), path = require('path');
const JSM = path.join(__dirname, 'npm', 'package', 'examples', 'jsm');
const order = [], mods = new Map();
function load(file) {
  file = path.normalize(file); if (mods.has(file)) return mods.get(file);
  const src = fs.readFileSync(file, 'utf8'), m = { file, id: 'M' + mods.size, src, deps: [] }; mods.set(file, m);
  const imp = /import\s+(\*\s+as\s+\w+|\{[^}]*\})\s+from\s+['"]([^'"]+)['"];?/g; let r;
  while ((r = imp.exec(src))) if (r[2] !== 'three') m.deps.push(load(path.resolve(path.dirname(file), r[2])));
  order.push(m); return m;
}
const names = s => s.replace(/[{}]/g, '').split(',').map(x => x.trim()).filter(Boolean).map(x => { const [a, b] = x.split(/\s+as\s+/); return [a.trim(), (b || a).trim()]; });
function wrap(m) {
  let s = m.src, exp = [];
  s = s.replace(/import\s+(\*\s+as\s+\w+|\{[^}]*\})\s+from\s+['"]([^'"]+)['"];?/g, (all, what, from) => {
    const src = from === 'three' ? 'THREE' : mods.get(path.normalize(path.resolve(path.dirname(m.file), from))).id;
    if (what.startsWith('*')) return `const ${what.split(/\s+as\s+/)[1].trim()} = ${src};`;
    return 'const { ' + names(what).map(([a, b]) => a === b ? a : `${a}: ${b}`).join(', ') + ` } = ${src};`;
  });
  s = s.replace(/export\s*\{([^}]*)\}\s*;?/g, (all, list) => { names(list).forEach(([a, b]) => exp.push([b, a])); return ''; });
  s = s.replace(/export\s+(default\s+)?(async\s+)?(function\*?|class|const|let|var)\s+([A-Za-z0-9_$]+)/g, (all, def, as, kw, name) => { exp.push([name, name]); return `${as || ''}${kw} ${name}`; });
  return `const ${m.id} = (function () {\n${s}\nreturn { ${exp.map(([o, i]) => o === i ? o : `${o}: ${i}`).join(', ')} };\n})();\n`;
}
const fbx = load(path.join(JSM, 'loaders', 'FBXLoader.js')), gltf = load(path.join(JSM, 'loaders', 'GLTFLoader.js')), sku = load(path.join(JSM, 'utils', 'SkeletonUtils.js'));
const out = `// Generated by tools/vh-engine/bundle-addons.js from three@0.160.0 examples/jsm (MIT). Do not edit.\n(function () {\n'use strict';\n` +
  order.map(wrap).join('\n') + `window.THREE_ADDONS = { FBXLoader: ${fbx.id}.FBXLoader, GLTFLoader: ${gltf.id}.GLTFLoader, SkeletonUtils: ${sku.id} };\n})();\n`;
const dst = path.join(__dirname, 'template', 'vendor', 'three-addons.js'); fs.writeFileSync(dst, out);
console.log('wrote', dst, (out.length / 1024).toFixed(0) + ' KB,', order.length, 'modules:', order.map(m => path.basename(m.file)).join(', '));
